function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Bug: read-modify-write race — concurrent increment() calls read the same
// value before any of them writes back, so updates are lost.
class AsyncCounter {
  constructor() {
    this.value = 0;
  }
  async increment() {
    const current = this.value;
    await delay(5);
    this.value = current + 1;
    return this.value;
  }
  get() {
    return this.value;
  }
}

module.exports = { AsyncCounter };
